<?php declare(strict_types=1);require __DIR__.'/../config/bootstrap.php';$raw=file_get_contents('php://input');$payload=json_decode($raw,true)??[];$eventId=(string)($payload['id']??$payload['event_id']??$payload['order_id']??hash('sha256',$raw));$providerOrder=(string)($payload['order_id']??$payload['id']??'');$status=strtolower((string)($payload['status']??$payload['state']??''));try{$pdo=db();$pdo->beginTransaction();$ins=$pdo->prepare('INSERT IGNORE INTO webhook_events(provider,event_id,payload,processed) VALUES("topup.dev",?,?,0)');$ins->execute([$eventId,$raw]);if($ins->rowCount()>0&&$providerOrder!==''){$q=$pdo->prepare('SELECT id FROM orders WHERE provider_order_id=? LIMIT 1');$q->execute([$providerOrder]);$o=$q->fetch();if($o){$delivery=match($status){'done','completed','fulfilled','success'=>'delivered','failed','error','cancelled'=>'failed',default=>'processing'};$pdo->prepare('UPDATE orders SET delivery_status=?,delivered_at=CASE WHEN ?="delivered" THEN NOW() ELSE delivered_at END WHERE id=?')->execute([$delivery,$delivery,$o['id']]);$pdo->prepare('INSERT INTO order_events(order_id,event_type,status,message,payload) VALUES(?,?,?,?,?)')->execute([$o['id'],'topup_callback',$status,'Topup.dev callback',$raw]);}$pdo->prepare('UPDATE webhook_events SET processed=1 WHERE provider="topup.dev" AND event_id=?')->execute([$eventId]);}$pdo->commit();http_response_code(200);echo json_encode(['received'=>true]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();http_response_code(500);echo json_encode(['error'=>'Webhook processing failed']);}
